class RandomizedSet {
  private s = new Set<number>();

  insert(val: number): boolean {
    if (this.s.has(val)) return false;
    this.s.add(val);
    return true;
  }

  remove(val: number): boolean {
    return this.s.delete(val);
  }

  getRandom(): number {
    const arr = [...this.s];
    return arr[Math.floor(Math.random() * arr.length)];
  }
}

