class RandomizedSet {
  private vals: number[] = [];
  private pos = new Map<number, number>();

  insert(val: number): boolean {
    if (this.pos.has(val)) return false;
    this.pos.set(val, this.vals.length);
    this.vals.push(val);
    return true;
  }

  remove(val: number): boolean {
    const i = this.pos.get(val);
    if (i === undefined) return false;
    const last = this.vals[this.vals.length - 1];
    this.vals[i] = last;
    this.pos.set(last, i); // before the delete, in case val is last
    this.vals.pop();
    this.pos.delete(val);
    return true;
  }

  getRandom(): number {
    return this.vals[Math.floor(Math.random() * this.vals.length)];
  }
}

