            return False
        self.pos[val] = len(self.vals)
        self.vals.append(val)
        return True

    def remove(self, val: int) -> bool:
        i = self.pos.get(val)
        if i is None:
            return False
        last = self.vals[-1]
        self.vals[i] = last
        self.pos[last] = i  # before the delete, in case val is last
        self.vals.pop()
        del self.pos[val]
        return True

    def getRandom(self) -> int:
        return self.vals[random.randrange(len(self.vals))]

